def merge(intervals):
    """Merge overlapping or touching [start, end] intervals.

    The input list and its interval lists are not modified.
    """
    if not intervals:
        return []

    ordered = sorted((list(interval) for interval in intervals), key=lambda x: (x[0], x[1]))
    merged = [ordered[0][:]]

    for start, end in ordered[1:]:
        if start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged
